#!/bin/bash
# Generated by dsh-super-injector dev_scaffold_plugin; extended for this plugin.
# Build: compile src/index.ts → lib/ (host tsc), typecheck the browser half, and
# expose the checkout's tsdown as node_modules/.bin/tsdown so `npm run
# build:client` can bundle src/client → lib/client.js.
# Requires DSH_CHECKOUT pointing at a dsh source checkout (auto-probe below).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

# DSH_CHECKOUT 探测：环境变量 → 常见路径（home 下 dsh-harness / deepseek-harness）
CHECKOUT="${DSH_CHECKOUT:-}"
if [ -z "$CHECKOUT" ]; then
  for candidate in "$HOME/dsh-harness" "$HOME/deepseek-harness" "$HOME/dsh" "$HOME/.dsh/dsh-harness"; do
    if [ -d "$candidate/packages" ]; then CHECKOUT="$candidate"; break; fi
  done
fi
if [ -z "$CHECKOUT" ] || [ ! -d "$CHECKOUT/packages" ]; then
  echo "build: cannot locate the dsh checkout (set DSH_CHECKOUT)" >&2
  exit 1
fi

TSC="$CHECKOUT/node_modules/.bin/tsc"
if [ ! -x "$TSC" ] && [ ! -f "$TSC.cmd" ]; then
  echo "build: tsc not found at $TSC" >&2
  exit 1
fi

link_pkg() {
  local target="$CHECKOUT/$2"
  if [ ! -e "$target" ]; then
    echo "build: dependency target missing: $target" >&2
    exit 1
  fi
  node -e "
    const fs = require('fs');
    const path = require('path');
    const link = path.resolve(process.argv[1]);
    const target = path.resolve(process.argv[2]);
    fs.rmSync(link, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(link), { recursive: true });
    fs.symlinkSync(target, link, process.platform === 'win32' ? 'junction' : 'dir');
  " "node_modules/$1" "$target"
}

# Same as link_pkg, for targets outside the checkout (pnpm's content store).
link_abs() {
  local target="$2"
  if [ ! -e "$target" ]; then
    echo "build: dependency target missing: $target" >&2
    exit 1
  fi
  node -e "
    const fs = require('fs');
    const path = require('path');
    const link = path.resolve(process.argv[1]);
    const target = path.resolve(process.argv[2]);
    fs.rmSync(link, { recursive: true, force: true });
    fs.mkdirSync(path.dirname(link), { recursive: true });
    fs.symlinkSync(target, link, process.platform === 'win32' ? 'junction' : 'dir');
  " "node_modules/$1" "$target"
}

echo "=== Linking build dependencies (checkout: $CHECKOUT) ==="
mkdir -p node_modules/@deepseek-ai
node -e "const fs=require('fs');fs.rmSync('node_modules/@standard-schema',{recursive:true,force:true})"
link_pkg cordis vendor/cordis
link_pkg cosmokit vendor/cosmokit
link_pkg schemastery vendor/schemastery
# @types/node（编译类型；checkout 自带）
link_pkg @types/node node_modules/@types/node

# react 及其类型只服务 browser 半边的类型检查；打包时 react 是 external。
REACT_DIR="$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname 'react@*' 2>/dev/null | sort -V | tail -1)"
TYPES_REACT_DIR="$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname '@types+react@*' 2>/dev/null | sort -V | tail -1)"
if [ -n "$REACT_DIR" ]; then link_abs react "$REACT_DIR/node_modules/react"; fi
if [ -n "$TYPES_REACT_DIR" ]; then link_abs @types/react "$TYPES_REACT_DIR/node_modules/@types/react"; fi

STD_SCHEMA=$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 1 -type d -iname '@standard-schema+spec@*' 2>/dev/null | head -1)
if [ -n "$STD_SCHEMA" ]; then
  node -e "
    const fs = require('fs');
    const path = require('path');
    fs.rmSync('node_modules/@standard-schema', { recursive: true, force: true });
    fs.mkdirSync('node_modules/@standard-schema', { recursive: true });
    fs.symlinkSync(path.resolve(process.argv[1]), path.resolve('node_modules/@standard-schema/spec'), process.platform === 'win32' ? 'junction' : 'dir');
  " "$STD_SCHEMA/node_modules/@standard-schema/spec"
fi

# tsdown 由 checkout 提供；暴露成 .bin/tsdown，npm run build:client 才能找到它。
TSDOWN_RUN="$CHECKOUT/node_modules/tsdown/dist/run.mjs"
if [ ! -f "$TSDOWN_RUN" ]; then
  TSDOWN_RUN="$(find "$CHECKOUT/node_modules/.pnpm" -maxdepth 8 -path '*/node_modules/tsdown/dist/run.mjs' 2>/dev/null | head -1)"
fi
if [ -n "$TSDOWN_RUN" ] && [ -f "$TSDOWN_RUN" ]; then
  mkdir -p node_modules/.bin
  printf '#!/bin/sh\nexec "%s" "%s" "$@"\n' "$(command -v node)" "$TSDOWN_RUN" > node_modules/.bin/tsdown
  chmod +x node_modules/.bin/tsdown
else
  echo "build: tsdown not found in the checkout; npm run build:client will fail" >&2
fi

echo "=== Compiling src/index.ts → lib (host) ==="
"$TSC" -p tsconfig.json
echo "=== Typechecking src/client (browser half) ==="
"$TSC" -p tsconfig.client.json
echo "=== Build complete ==="
